/*
 * EDUCATION TECHNOLOGY 09 / VERIFIED DIGITAL CREDENTIAL
 * Native Canvas 2D. One continuous scene. Seamless 25-second loop.
 * time is supplied in SECONDS. No assets, fonts, DOM, timers or dependencies.
 * Export target: 3840 x 2160 / 60 fps / 100,000,000 bits per second.
 * Actual MP4 bitrate is controlled by the video encoder, not Canvas.
 * Revision: fixed geometry and a shared scan / transfer / verify timeline.
 */
function draw(ctx, time, width, height) {
  if (!ctx || !Number.isFinite(time) || !Number.isFinite(width) ||
      !Number.isFinite(height) || width <= 0 || height <= 0) return;
  const t = time;
  const duration = 25;
  const loopT = ((t % duration) + duration) % duration;
  const sceneProgress = loopT / duration;
  const minSide = Math.min(width, height);

  const TAU=Math.PI*2;
  const scale=Math.min(minSide/1080,width/1920);
  const ink='#132030';
  const cyan='#80c7d1';
  const mint='#a5d9c4';
  const gold='#d6bd84';
  const fract=n=>n-Math.floor(n);
  const clamp=n=>Math.max(0,Math.min(1,n));
  const ease=n=>{n=clamp(n);return n*n*n*(n*(n*6-15)+10);};

  // Four identical 6.25 s verification cycles. All animated accents share
  // this clock; the certificate, chip, seal and ribbons stay rigid.
  // Scan: 0.40-1.80 s; transfer: 2.05-3.35 s; verify: 3.45-4.25 s.
  // Hold, then ease back to neutral by 5.95 s, before the cycle wraps.
  const cycleT=loopT%(duration/4);
  const progress=(start,end)=>ease((cycleT-start)/(end-start));
  const window=(start,entered,leaving,end)=>
    progress(start,entered)*(1-progress(leaving,end));
  const reset=1-progress(5.25,5.95);
  const scan=progress(0.40,1.80);
  const scanAlpha=window(0.20,0.40,1.80,2.00);
  const transfer=progress(2.05,3.35);
  const transferAlpha=window(2.05,2.25,3.15,3.35);
  const checkProgress=progress(3.45,4.25);
  const checkAlpha=reset;

  function rr(x,y,w,h,r,fill,stroke,lw){
    r=Math.min(r,w/2,h/2);
    ctx.beginPath();ctx.moveTo(x+r,y);ctx.lineTo(x+w-r,y);
    ctx.quadraticCurveTo(x+w,y,x+w,y+r);ctx.lineTo(x+w,y+h-r);
    ctx.quadraticCurveTo(x+w,y+h,x+w-r,y+h);ctx.lineTo(x+r,y+h);
    ctx.quadraticCurveTo(x,y+h,x,y+h-r);ctx.lineTo(x,y+r);
    ctx.quadraticCurveTo(x,y,x+r,y);ctx.closePath();
    if(fill){ctx.fillStyle=fill;ctx.fill();}
    if(stroke){ctx.strokeStyle=stroke;ctx.lineWidth=lw||2;ctx.stroke();}
  }
  function line(x1,y1,x2,y2,color,w){
    ctx.beginPath();ctx.moveTo(x1,y1);ctx.lineTo(x2,y2);
    ctx.strokeStyle=color;ctx.lineWidth=w||3;ctx.stroke();
  }
  function dot(x,y,r,fill,stroke,w){
    ctx.beginPath();ctx.arc(x,y,r,0,TAU);ctx.fillStyle=fill;ctx.fill();
    if(stroke){ctx.strokeStyle=stroke;ctx.lineWidth=w||2;ctx.stroke();}
  }
  function tick(x,y,size,amount,color,w){
    amount=clamp(amount);
    if(amount<=0)return;
    const pts=[[x-size*0.48,y],[x-size*0.12,y+size*0.32],[x+size*0.53,y-size*0.43]];
    const l1=Math.hypot(pts[1][0]-pts[0][0],pts[1][1]-pts[0][1]);
    const l2=Math.hypot(pts[2][0]-pts[1][0],pts[2][1]-pts[1][1]);
    const length=(l1+l2)*clamp(amount);
    ctx.save();ctx.globalAlpha*=ease(amount/0.12);
    ctx.beginPath();ctx.moveTo(pts[0][0],pts[0][1]);
    if(length<l1){const u=length/l1;ctx.lineTo(pts[0][0]+(pts[1][0]-pts[0][0])*u,pts[0][1]+(pts[1][1]-pts[0][1])*u);}
    else{ctx.lineTo(pts[1][0],pts[1][1]);const u=(length-l1)/l2;
      ctx.lineTo(pts[1][0]+(pts[2][0]-pts[1][0])*u,pts[1][1]+(pts[2][1]-pts[1][1])*u);}
    ctx.strokeStyle=color;ctx.lineWidth=w;ctx.stroke();ctx.restore();
  }
  function cubic(p,u){
    const v=1-u;
    return {x:v*v*v*p[0]+3*v*v*u*p[2]+3*v*u*u*p[4]+u*u*u*p[6],
      y:v*v*v*p[1]+3*v*v*u*p[3]+3*v*u*u*p[5]+u*u*u*p[7]};
  }
  function dataChannel(){
    // Endpoints sit underneath the chip contact and the seal respectively.
    // Arc-length lookup avoids a speed jump on the middle of the curve.
    const p=[-180,20,-30,20,-30,96,154,96];
    ctx.beginPath();ctx.moveTo(p[0],p[1]);ctx.bezierCurveTo(p[2],p[3],p[4],p[5],p[6],p[7]);
    ctx.strokeStyle='#becbc3';ctx.lineWidth=11;ctx.stroke();
    ctx.strokeStyle='#748f95';ctx.lineWidth=2.4;ctx.stroke();
    const lengths=[0];let previous=cubic(p,0);
    const samples=96;
    for(let i=1;i<=samples;i++){
      const next=cubic(p,i/samples);
      lengths.push(lengths[i-1]+Math.hypot(next.x-previous.x,next.y-previous.y));previous=next;
    }
    const target=transfer*lengths[samples];
    let k=1;while(k<samples&&lengths[k]<target)k++;
    const u=(k-1+(target-lengths[k-1])/(lengths[k]-lengths[k-1]))/samples;
    const pos=cubic(p,u);
    ctx.save();ctx.globalAlpha*=transferAlpha;
    dot(pos.x,pos.y,5.5,cyan,ink,2);dot(pos.x,pos.y,1.5,'#f0edda');ctx.restore();
  }
  function securityTrack(){
    const x=-480,y=-290,w=960,h=580,r=28;
    ctx.beginPath();ctx.moveTo(x+r,y);ctx.lineTo(x+w-r,y);
    ctx.arc(x+w-r,y+r,r,-Math.PI/2,0);
    ctx.lineTo(x+w,y+h-r);ctx.arc(x+w-r,y+h-r,r,0,Math.PI/2);
    ctx.lineTo(x+r,y+h);ctx.arc(x+r,y+h-r,r,Math.PI/2,Math.PI);
    ctx.lineTo(x,y+r);ctx.arc(x+r,y+r,r,Math.PI,Math.PI*1.5);ctx.closePath();
    ctx.strokeStyle='#bdaf84';ctx.lineWidth=1.3;ctx.stroke();
    const horizontal=w-2*r,vertical=h-2*r,arc=Math.PI*r/2;
    const lengths=[horizontal,arc,vertical,arc,horizontal,arc,vertical,arc];
    let remaining=fract(2*sceneProgress+0.14)*lengths.reduce((a,b)=>a+b,0);
    let side=0;while(side<7&&remaining>lengths[side])remaining-=lengths[side++];
    let px,py,angle;
    if(side===0){px=x+r+remaining;py=y;}
    else if(side===1){angle=-Math.PI/2+remaining/r;px=x+w-r+r*Math.cos(angle);py=y+r+r*Math.sin(angle);}
    else if(side===2){px=x+w;py=y+r+remaining;}
    else if(side===3){angle=remaining/r;px=x+w-r+r*Math.cos(angle);py=y+h-r+r*Math.sin(angle);}
    else if(side===4){px=x+w-r-remaining;py=y+h;}
    else if(side===5){angle=Math.PI/2+remaining/r;px=x+r+r*Math.cos(angle);py=y+h-r+r*Math.sin(angle);}
    else if(side===6){px=x;py=y+h-r-remaining;}
    else{angle=Math.PI+remaining/r;px=x+r+r*Math.cos(angle);py=y+r+r*Math.sin(angle);}
    dot(px,py,4.2,cyan,ink,1.6);
  }
  function ribbon(x,y,side){
    // Mirrored rigid tails. Their full silhouettes, including strokes,
    // remain inside the inner security border throughout the loop.
    ctx.save();ctx.translate(x,y);ctx.rotate(-side*0.055);
    ctx.beginPath();ctx.moveTo(-22,0);ctx.lineTo(22,0);
    if(side<0){ctx.lineTo(14,99);ctx.lineTo(-9,80);ctx.lineTo(-32,99);}
    else{ctx.lineTo(32,99);ctx.lineTo(9,80);ctx.lineTo(-14,99);}
    ctx.closePath();ctx.fillStyle=side<0?'#7188aa':'#537c94';ctx.fill();
    ctx.strokeStyle=ink;ctx.lineWidth=3.5;ctx.stroke();
    line(side<0?-3:3,20,side<0?-9:9,71,'#b0c3cc',2.4);ctx.restore();
  }
  function rosette(x,y){
    const points=[];
    for(let i=0;i<40;i++){
      const a=i*TAU/40;const r=i%2===0?130:118;
      points.push({x:x+r*Math.cos(a),y:y+r*Math.sin(a)});
    }
    ctx.beginPath();ctx.moveTo((points[39].x+points[0].x)/2,(points[39].y+points[0].y)/2);
    for(let i=0;i<40;i++){
      const next=points[(i+1)%40];
      ctx.quadraticCurveTo(points[i].x,points[i].y,(points[i].x+next.x)/2,(points[i].y+next.y)/2);
    }
    ctx.closePath();ctx.fillStyle=gold;ctx.fill();ctx.strokeStyle=ink;ctx.lineWidth=4;ctx.stroke();
  }

  ctx.save();
  try{
    ctx.setTransform(1,0,0,1,0,0);ctx.globalAlpha=1;
    ctx.globalCompositeOperation='source-over';ctx.shadowBlur=0;ctx.shadowColor='transparent';
    ctx.shadowOffsetX=0;ctx.shadowOffsetY=0;ctx.filter='none';
    ctx.setLineDash([]);ctx.lineDashOffset=0;ctx.lineCap='round';ctx.lineJoin='round';
    const bg=ctx.createLinearGradient(0,0,width,height);
    bg.addColorStop(0,'#272137');bg.addColorStop(0.52,'#242b3d');bg.addColorStop(1,'#192f40');
    ctx.fillStyle=bg;ctx.fillRect(0,0,width,height);
    ctx.translate(width/2,height/2-9*scale);ctx.scale(scale,scale);

    const paper=ctx.createLinearGradient(-520,-330,520,330);
    paper.addColorStop(0,'#f0ecdf');paper.addColorStop(1,'#e3e4d9');
    rr(-520,-330,1040,660,25,paper,ink,6);
    rr(-496,-306,992,612,18,null,'#ad9b6c',3);
    securityTrack();
    // Four restrained corner ornaments stay clear of the security trace.
    for(const sx of [-1,1])for(const sy of [-1,1]){
      const x=sx*464,y=sy*271;
      line(x,y,x-sx*16,y,'#bdab7c',2.6);
      line(x,y,x,y-sy*16,'#bdab7c',2.6);
    }

    // Header icon, title marks and status panel share the same centerline.
    rr(-432,-274,64,64,14,'#b8a577',ink,2.7);
    rr(-416,-261,32,38,5,'#e4ddbd','#7f836f',1.5);
    line(-410,-251,-392,-251,'#8a947f',2.2);
    line(-410,-243,-398,-243,'#8a947f',2.2);
    tick(-400,-233,15,1,'#64827e',2.3);
    line(-336,-254,244,-254,'#657f8c',7);
    line(-336,-230,119,-230,'#a0b1b0',4.3);
    rr(304,-264,128,44,9,'#d6decd','#a2b5ae',1.5);
    const stageStarts=[0.35,0.90,1.40,2.10,2.85,3.70];
    for(let i=0;i<6;i++){
      const active=progress(stageStarts[i],stageStarts[i]+0.45)*reset;
      ctx.save();ctx.globalAlpha*=0.35+0.55*active;
      rr(318.5+i*18,-251,9,18,2.5,i<3?'#608d96':'#8a8da6');ctx.restore();
    }
    line(-432,-190,432,-190,'#baa982',2);
    for(const x of [-432,432])dot(x,-190,3.1,'#d7bd85','#998761',1.2);
    line(-432,-152,112,-152,'#7f939b',4.5);
    line(-432,-128,44,-128,'#9db0b1',3.5);
    line(-432,-104,140,-104,'#9db0b1',3.5);
    line(-432,-80,-52,-80,'#bdc8bf',3.2);

    dataChannel();
    // Chip geometry uses one local origin and symmetric contact spacing.
    // Contacts render behind the housing, so their joins stay clean.
    ctx.save();ctx.translate(-280,34);
    for(let i=0;i<4;i++){
      rr(-63+i*37,-79,15,22,4,'#90a7af',ink,2);
      rr(-63+i*37,57,15,22,4,'#90a7af',ink,2);
      rr(-102,-48+i*28,25,12,3,'#90a7af',ink,2);
      rr(77,-48+i*28,25,12,3,'#90a7af',ink,2);
    }
    rr(-85,-65,170,130,18,'#4f7187',ink,4);
    rr(-71,-51,142,102,11,'#1e3e53','#94b7bd',1.7);
    for(let row=0;row<3;row++)for(let col=0;col<3;col++){
      const active=progress(0.58+row*0.25,1.06+row*0.25)*reset;
      rr(-48+col*36,-31+row*24,24,14,4,'#436578');
      ctx.save();ctx.globalAlpha*=0.22+0.64*active;
      rr(-48+col*36,-31+row*24,24,14,4,row===1?gold:cyan);ctx.restore();
    }
    ctx.save();rr(-69,-49,138,98,10,null);ctx.clip();
    const scanY=-39+78*scan;
    ctx.globalAlpha*=scanAlpha;
    ctx.save();ctx.globalAlpha*=0.13;rr(-65,scanY-7,130,14,4,cyan);ctx.restore();
    ctx.save();ctx.globalAlpha*=0.8;line(-61,scanY,61,scanY,'#c7ebe0',2.2);ctx.restore();
    ctx.restore();
    ctx.restore();
    line(-365,147,-195,147,'#8ea5aa',3.2);
    line(-365,163,-246,163,'#b0bfba',2.7);
    rr(-402,216,244,34,8,'#d1dcce','#a6b9b2',1.4);
    for(let i=0;i<8;i++){
      rr(-382+i*27,227,15,12,3,i<3?'#879b9a':'#a5b8af');
      const start=2.05+i*0.17;
      ctx.save();ctx.globalAlpha*=0.48*progress(start,start+0.28)*reset;
      rr(-382+i*27,227,15,12,3,cyan);ctx.restore();
    }

    // Stable seal origin; attached parts never drift, scale or wobble.
    ctx.save();ctx.translate(276,96);
    ribbon(-39,79,-1);ribbon(39,79,1);
    rosette(0,0);
    dot(0,0,107,'#e6d4a2','#9d875c',2.8);
    dot(0,0,88,'#243e52','#b5a374',3);
    for(let i=0;i<3;i++)rr(-16+i*12,-56,8,8,2,'#9ababc');
    tick(-2,9,81,1,'#42646c',8);
    ctx.save();ctx.globalAlpha*=checkAlpha;
    tick(-2,9,81,checkProgress,mint,8);ctx.restore();
    for(let i=0;i<4;i++){
      rr(-33+i*18,63,12,5,2.5,'#4a696d');
      const start=4.20+i*0.12;
      ctx.save();ctx.globalAlpha*=progress(start,start+0.28)*reset;
      rr(-33+i*18,63,12,5,2.5,cyan);ctx.restore();
    }
    ctx.restore();
  }finally{ctx.restore();}
}

draw.duration=25;
draw.fps=60;
draw.exportSettings={width:3840,height:2160,fps:60,duration:25,bitrate:100000000};

/*
 * EDUCATION TECHNOLOGY 10 / IMMERSIVE LEARNING HEADSET
 * Native Canvas 2D. One continuous scene. Seamless 25-second loop.
 * time is supplied in SECONDS. No assets, fonts, DOM, timers or dependencies.
 * Export target: 3840 x 2160 / 60 fps / 100,000,000 bits per second.
 * Actual MP4 bitrate is controlled by the video encoder, not Canvas.
 */
function draw(ctx, time, width, height) {
  const t = time;
  const duration = 25;
  const sceneCount = 1;
  const loopT = ((t % duration) + duration) % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;
  const minSide = Math.min(width, height);
  if (!(width > 0 && height > 0) || !Number.isFinite(t)) return;

  const TAU=Math.PI*2;
  const phase=TAU*(currentScene+sceneProgress)/sceneCount;
  const scale=Math.min(minSide/1080,width/1920);
  const ink='#0d1c2f';
  const cyan='#83cbd8';
  const mint='#9ad6c0';
  const lilac='#b5b0e6';
  const sand='#dfbd90';
  const fract=n=>n-Math.floor(n);
  const clamp=n=>Math.max(0,Math.min(1,n));
  const smooth=n=>{n=clamp(n);return n*n*(3-2*n);};
  const assembly=0.5-0.5*Math.cos(phase*2+0.35);
  const focus=0.5-0.5*Math.cos(phase*3+0.4);
  const baseShift=8*Math.sin(phase);
  const leftX=-404+baseShift,rightX=-154+baseShift;
  const apexX=-279+20*Math.sin(phase*2);
  const apexY=-39+6*Math.cos(phase*2);
  const focusX=leftX+20+(rightX-leftX-40)*focus;
  const tiles=[];
  for(let i=0;i<3;i++)tiles.push({x:123+i*119+(i-1)*16*(1-assembly),
    y:-15+(i===1?14:-10)*(1-assembly)});

  function rr(x,y,w,h,r,fill,stroke,lw){
    r=Math.min(r,w/2,h/2);
    ctx.beginPath();ctx.moveTo(x+r,y);ctx.lineTo(x+w-r,y);
    ctx.quadraticCurveTo(x+w,y,x+w,y+r);ctx.lineTo(x+w,y+h-r);
    ctx.quadraticCurveTo(x+w,y+h,x+w-r,y+h);ctx.lineTo(x+r,y+h);
    ctx.quadraticCurveTo(x,y+h,x,y+h-r);ctx.lineTo(x,y+r);
    ctx.quadraticCurveTo(x,y,x+r,y);ctx.closePath();
    if(fill){ctx.fillStyle=fill;ctx.fill();}
    if(stroke){ctx.strokeStyle=stroke;ctx.lineWidth=lw||2;ctx.stroke();}
  }
  function line(x1,y1,x2,y2,color,w){
    ctx.beginPath();ctx.moveTo(x1,y1);ctx.lineTo(x2,y2);
    ctx.strokeStyle=color;ctx.lineWidth=w||3;ctx.stroke();
  }
  function dot(x,y,r,fill,stroke,w){
    ctx.beginPath();ctx.arc(x,y,r,0,TAU);ctx.fillStyle=fill;ctx.fill();
    if(stroke){ctx.strokeStyle=stroke;ctx.lineWidth=w||2;ctx.stroke();}
  }
  function visor(inset){
    const w=558-inset,top=-152+inset,bottom=248-inset;
    ctx.beginPath();ctx.moveTo(-480,top);ctx.lineTo(480,top);
    ctx.quadraticCurveTo(w,top,w,-74);ctx.lineTo(w,169);
    ctx.quadraticCurveTo(w,bottom,480,bottom);ctx.lineTo(113,bottom);
    ctx.quadraticCurveTo(85,bottom,78,224-inset*0.6);
    ctx.lineTo(49,191-inset*0.8);ctx.quadraticCurveTo(0,150-inset*0.45,-49,191-inset*0.8);
    ctx.lineTo(-78,224-inset*0.6);ctx.quadraticCurveTo(-85,bottom,-113,bottom);
    ctx.lineTo(-480,bottom);ctx.quadraticCurveTo(-w,bottom,-w,169);
    ctx.lineTo(-w,-74);ctx.quadraticCurveTo(-w,top,-480,top);ctx.closePath();
  }
  function band(){
    ctx.beginPath();ctx.moveTo(-450,-79);
    ctx.bezierCurveTo(-450,-287,-224,-393,0,-393);
    ctx.bezierCurveTo(224,-393,450,-287,450,-79);
  }
  function grid(x){
    for(let i=0;i<9;i++)line(x+21+i*47,-66,x+21+i*47,130,'#294b63',1);
    for(let i=0;i<5;i++)line(x+18,-57+i*44,x+409,-57+i*44,'#294b63',1);
  }
  function transfer(a,b,offset){
    const x1=a.x+72,y1=a.y+36,x2=b.x,y2=b.y+36;
    const dx=(x2-x1)/3;
    ctx.beginPath();ctx.moveTo(x1,y1);ctx.bezierCurveTo(x1+dx,y1,x2-dx,y2,x2,y2);
    ctx.strokeStyle='#527b8e';ctx.lineWidth=2.2;ctx.stroke();
    const q=fract(3*sceneProgress+offset),v=1-q;
    const x=v*v*v*x1+3*v*v*q*(x1+dx)+3*v*q*q*(x2-dx)+q*q*q*x2;
    const y=v*v*v*y1+3*v*v*q*y1+3*v*q*q*y2+q*q*q*y2;
    ctx.save();ctx.globalAlpha=smooth(Math.min(q/0.09,(1-q)/0.09));
    dot(x,y,3.2,mint,ink,1.5);ctx.restore();
  }

  ctx.save();
  try{
    ctx.setTransform(1,0,0,1,0,0);ctx.globalAlpha=1;
    ctx.globalCompositeOperation='source-over';ctx.shadowBlur=0;ctx.shadowColor='transparent';
    ctx.setLineDash([]);ctx.lineDashOffset=0;ctx.lineCap='round';ctx.lineJoin='round';
    const bg=ctx.createLinearGradient(0,0,width,height);
    bg.addColorStop(0,'#222238');bg.addColorStop(0.52,'#202d40');bg.addColorStop(1,'#1a3543');
    ctx.fillStyle=bg;ctx.fillRect(0,0,width,height);
    ctx.translate(width/2,height/2+38*scale);ctx.scale(scale,scale);

    // Front-view band and strap are flat vector contours, without perspective.
    band();ctx.strokeStyle=ink;ctx.lineWidth=54;ctx.stroke();
    band();ctx.strokeStyle='#5c7694';ctx.lineWidth=42;ctx.stroke();
    band();ctx.strokeStyle='#94aabc';ctx.lineWidth=2.5;ctx.stroke();
    rr(-36,-390,72,267,17,'#526c8d',ink,4);
    line(-23,-370,-23,-158,'#8fa8ba',2.4);
    const buckleY=-315+6*Math.sin(phase);
    rr(-52,buckleY,104,49,12,'#7f94ae',ink,4);
    rr(-38,buckleY+12,76,24,6,'#36516d','#acbfca',1.5);
    for(let i=0;i<3;i++)line(-22+i*22,buckleY+18,-22+i*22,buckleY+30,'#9fb7c4',2.1);

    // Side controls mount behind the casing and retain a constant silhouette.
    rr(-615,-45,64,155,20,'#4b6a87',ink,4.5);
    for(let i=0;i<2;i++){
      rr(-600,-23+i*62,31,35,6,'#193b52','#8eabba',1.5);
      line(-592,-11+i*62,-577,-11+i*62,'#a1c2c7',2.3);
      line(-592,-1+i*62,-580,-1+i*62,'#648d9f',2);
    }
    rr(544,-19,73,121,21,'#5f7b98',ink,4.5);
    dot(584,43,21,'#25465f',ink,3);
    dot(584,43,14,'#688e9e','#afc8cd',1.5);
    const knobAngle=-Math.PI/2+0.12*Math.sin(phase*2);
    line(584,43,584+10*Math.cos(knobAngle),43+10*Math.sin(knobAngle),mint,2.5);

    const casing=ctx.createLinearGradient(-540,-150,540,248);
