/*
 * EDUCATION TECHNOLOGY 02 / INTERACTIVE SMARTBOARD
 * One continuous scene. Deterministic, seamless 25-second loop.
 * Native Canvas 2D only; no assets, fonts, timers, or external dependencies.
 * Export target: 3840 x 2160, 60 fps, 100,000,000 bits/s.
 * Bitrate is an encoder setting; draw() only generates the canvas artwork.
 */
function draw(ctx, time, width, height) {
  const t = time;
  const duration = 25;
  const sceneCount = 1;
  const loopT = ((t % duration) + duration) % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;
  const minSide = Math.min(width, height);
  if (!(width > 0 && height > 0) || !Number.isFinite(t)) return;

  const TAU = Math.PI * 2;
  // Start partway through the stroke so the loop seam carries ongoing motion.
  const phase = TAU * (currentScene + sceneProgress) / sceneCount + 0.37;
  const scale = Math.min(minSide / 1080, width / 1920);
  const ink = '#0a1722';
  const mint = '#80d9c4';
  const coral = '#e8a28e';
  const sand = '#e3ca92';
  const amplitude = 142 + 23 * Math.sin(phase);
  const slope = 25 * Math.sin(phase + 0.7);
  const penU = 0.5 - 0.5 * Math.cos(phase * 2);
  const curveX = u => -430 + 575 * u;
  const curveY = u => 83 - amplitude * 4 * u * (1 - u) + slope * (u - 0.5);
  const penX = curveX(penU);
  const penY = curveY(penU);
  const penDX = 0.48;
  const penDY = -Math.sqrt(1 - penDX * penDX);
  const penTopX = penX + penDX * 96;
  const penTopY = penY + penDY * 96;

  function rr(x, y, w, h, r, fill, stroke, lw) {
    r = Math.min(r, w / 2, h / 2);
    ctx.beginPath();
    ctx.moveTo(x + r, y); ctx.lineTo(x + w - r, y);
    ctx.quadraticCurveTo(x + w, y, x + w, y + r);
    ctx.lineTo(x + w, y + h - r);
    ctx.quadraticCurveTo(x + w, y + h, x + w - r, y + h);
    ctx.lineTo(x + r, y + h);
    ctx.quadraticCurveTo(x, y + h, x, y + h - r);
    ctx.lineTo(x, y + r);
    ctx.quadraticCurveTo(x, y, x + r, y);
    ctx.closePath();
    if (fill) { ctx.fillStyle = fill; ctx.fill(); }
    if (stroke) { ctx.strokeStyle = stroke; ctx.lineWidth = lw || 2; ctx.stroke(); }
  }

  function segment(x1, y1, x2, y2, color, w) {
    ctx.beginPath(); ctx.moveTo(x1, y1); ctx.lineTo(x2, y2);
    ctx.strokeStyle = color; ctx.lineWidth = w || 3; ctx.stroke();
  }

  function dot(x, y, r, color, stroke, lw) {
    ctx.beginPath(); ctx.arc(x, y, r, 0, TAU);
    ctx.fillStyle = color; ctx.fill();
    if (stroke) { ctx.strokeStyle = stroke; ctx.lineWidth = lw || 2; ctx.stroke(); }
  }

  function curvePath(end) {
    ctx.beginPath(); ctx.moveTo(curveX(0), curveY(0));
    ctx.quadraticCurveTo(-430 + 287.5 * end,
      curveY(0) + (slope * 0.5 - amplitude * 2) * end,
      curveX(end), curveY(end));
  }

  function dialIcon(x, y, mode, color) {
    rr(x, y, 38, 38, 9, '#243e49', '#52757e', 1.6);
    if (mode === 0) {
      ctx.beginPath(); ctx.moveTo(x + 9, y + 28);
      ctx.quadraticCurveTo(x + 19, y + 1, x + 29, y + 28);
      ctx.strokeStyle = color; ctx.lineWidth = 2.7; ctx.stroke();
    } else if (mode === 1) {
      segment(x + 9, y + 28, x + 9, y + 10, '#79969c', 2);
      segment(x + 9, y + 28, x + 28, y + 28, '#79969c', 2);
      segment(x + 9, y + 28, x + 28, y + 11, color, 2.7);
    } else {
      segment(x + 9, y + 19, x + 29, y + 19, '#79969c', 2.2);
      dot(x + 10 + 18 * penU, y + 19, 4, color);
    }
  }

  function controlCard(y, color, mode, value) {
    rr(252, y, 226, 88, 12, '#192f3a', '#4d6d77', 1.8);
    dialIcon(267, y + 14, mode, color);
    segment(321, y + 23, 457, y + 23, '#819ca5', 3.5);
    segment(321, y + 36, 405 + mode * 14, y + 36, '#4d6b77', 2.7);
    const x0 = 273;
    const x1 = 457;
    segment(x0, y + 68, x1, y + 68, '#395964', 5);
    for (let i = 0; i < 5; i++) {
      segment(x0 + (x1 - x0) * i / 4, y + 63, x0 + (x1 - x0) * i / 4, y + 73, '#627f86', 1.5);
    }
