    ctx.setTransform(1, 0, 0, 1, 0, 0);
    ctx.globalAlpha = 1;
    ctx.globalCompositeOperation = 'source-over';
    ctx.shadowBlur = 0;
    ctx.shadowColor = 'transparent';
    ctx.setLineDash([]); ctx.lineDashOffset = 0;
    ctx.lineCap = 'round'; ctx.lineJoin = 'round';
    const bg = ctx.createLinearGradient(0, 0, width, height);
    bg.addColorStop(0, '#17232b');
    bg.addColorStop(0.52, '#1b2c34');
    bg.addColorStop(1, '#113b40');
    ctx.fillStyle = bg; ctx.fillRect(0, 0, width, height);
    ctx.translate(width / 2, height / 2 - 22 * scale);
    ctx.scale(scale, scale);

    // Symmetric stand remains stationary; every animation is inside the device.
    for (const x of [-266, 266]) {
      rr(x - 17, 266, 34, 115, 9, '#657f89', ink, 4);
      segment(x - 5, 294, x - 5, 363, '#a3b6b9', 3);
    }
    rr(-362, 374, 724, 27, 12, '#718d96', ink, 4);
    rr(-346, 378, 692, 6, 3, '#a7babd');
    rr(-325, 400, 72, 8, 4, '#0d202b');
    rr(253, 400, 72, 8, 4, '#0d202b');

    const shell = ctx.createLinearGradient(-560, -324, 560, 292);
    shell.addColorStop(0, '#6c858d'); shell.addColorStop(1, '#3e626e');
    rr(-564, -324, 1128, 616, 34, shell, ink, 6);
    rr(-550, -310, 1100, 588, 25, '#263f4c', '#9aadb0', 2);
    rr(-527, -286, 1054, 514, 17, '#102730', ink, 4);

    // Content is clipped to the display, including the entire plotting tool.
    ctx.save();
    rr(-523, -282, 1046, 506, 14, '#102730'); ctx.clip();
    const screen = ctx.createLinearGradient(-520, -280, 520, 220);
    screen.addColorStop(0, '#18333e'); screen.addColorStop(1, '#112a35');
    ctx.fillStyle = screen; ctx.fillRect(-523, -282, 1046, 506);

    // A compact toolbar uses geometric glyphs, so no font is required.
    rr(-480, -264, 28, 18, 4, mint);
    segment(-440, -255, -335, -255, '#9ab4b8', 4);
    segment(-321, -255, -277, -255, '#577b84', 4);
    for (let i = 0; i < 3; i++) dot(435 + 19 * i, -255, 3.7, i === 0 ? mint : '#647f88');
    segment(224, -221, 224, 187, '#375964', 2);

    rr(-480, -203, 681, 369, 12, '#152f3a', '#385963', 1.7);
    // Stable grid and axes provide a reference for the changing function.
    for (let i = 0; i < 7; i++) {
      const x = -430 + 96 * i;
      segment(x, -181, x, 141, '#254652', 1.2);
    }
    for (let i = 0; i < 6; i++) {
      const y = -173 + 61 * i;
      segment(-459, y, 179, y, '#254652', 1.2);
    }
    segment(-449, 110, 177, 110, '#64848b', 2.4);
    segment(-430, -180, -430, 137, '#64848b', 2.4);
    segment(171, 105, 177, 110, '#64848b', 2.2);
    segment(171, 115, 177, 110, '#64848b', 2.2);
    segment(-435, -174, -430, -180, '#64848b', 2.2);
    segment(-425, -174, -430, -180, '#64848b', 2.2);

    curvePath(1);
    ctx.lineTo(curveX(1), 110); ctx.lineTo(curveX(0), 110); ctx.closePath();
    ctx.fillStyle = '#204a50'; ctx.fill();
    curvePath(1); ctx.strokeStyle = '#4b777c'; ctx.lineWidth = 4; ctx.stroke();

    // Focus projection and the point on the curve use exactly the same state.
    ctx.save(); ctx.setLineDash([5, 8]);
    segment(penX, penY + 8, penX, 109, '#a0bd9d', 1.8);
    ctx.restore();
    rr(penX - 11, 121, 22, 6, 3, sand);

    curvePath(penU);
    ctx.strokeStyle = mint; ctx.lineWidth = 5; ctx.stroke();
    for (const u of [0, 0.5, 1]) {
      dot(curveX(u), curveY(u), 6.5, '#17343e', '#93b7b2', 2.5);
    }
    dot(penX, penY, 6.1, mint, ink, 2);

    // Top rail, sliding carriage and telescopic stem form one connected tool.
    rr(-458, -232, 664, 12, 5, '#486b76', ink, 1.7);
    segment(-444, -226, 192, -226, '#8caaad', 2);
    for (const x of [-450, 198]) dot(x, -226, 3, '#b3c3c2', ink, 1);
    rr(penTopX - 6, -219, 12, penTopY + 219, 5, '#526f78', ink, 1.8);
    segment(penTopX - 1, -211, penTopX - 1, penTopY - 5, '#a7bcb8', 2);
    rr(penTopX - 20, -238, 40, 25, 6, '#a2beb7', ink, 2.8);
    segment(penTopX - 9, -225, penTopX + 9, -225, '#4b7275', 3);

    // Stylus body is a rigid vector shape. Its tip never leaves the curve.
    ctx.save(); ctx.translate(penX, penY);
    ctx.rotate(Math.atan2(penDY, penDX));
    ctx.beginPath(); ctx.moveTo(0, 0); ctx.lineTo(15, -5); ctx.lineTo(15, 5); ctx.closePath();
    ctx.fillStyle = '#e4dbc0'; ctx.fill(); ctx.strokeStyle = ink; ctx.lineWidth = 2; ctx.stroke();
    rr(13, -9, 76, 18, 6, mint, ink, 2.8);
    rr(76, -9, 20, 18, 5, '#a9bfc1', ink, 2.5);
    segment(27, -3, 65, -3, '#d0eee0', 2.5);
    segment(24, 5, 47, 5, '#3e978a', 2);
    dot(0, 0, 2.2, '#10242e');
    ctx.restore();

    controlCard(-209, mint, 0, (amplitude - 119) / 46);
    controlCard(-104, coral, 1, (slope + 25) / 50);
    controlCard(1, sand, 2, penU);

    // The lower measurement bracket and shape tools remain spatially separate.
    segment(-430, 190, 145, 190, '#607f88', 2);
    segment(-430, 184, -430, 196, '#829d9f', 2);
    segment(145, 184, 145, 196, '#829d9f', 2);
    for (let i = 0; i < 3; i++) {
      const x = 252 + i * 79;
      rr(x, 112, 68, 60, 10, '#203b46', '#52717a', 1.7);
      if (i === 0) {
        const cy = 142;
        ctx.beginPath(); ctx.moveTo(x + 18, cy + 11); ctx.lineTo(x + 34, cy - 12);
