    rr(-349, 278, 698, 8, 4, '#aac2b7');
    rr(-85, 292, 170, 6, 3, '#436660');
    rr(-486, 249, 48, 10, 5, '#729997');
    for (let i = 0; i < 3; i++) {
      const a = 0.45 + 0.25 * Math.sin(phase * 3 - i * 0.9);
      ctx.save(); ctx.globalAlpha = a;
      dot(437 + 18 * i, 254, 3.5, mint);
      ctx.restore();
    }
  } finally {
    ctx.restore();
  }
}

